
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hjs_b97x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hjs_b97x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.250481381129722e+00, -3.187292140764575e+00, -3.098762165478279e+00, -2.976158515222782e+00, -2.809177385647233e+00, -2.587157206741950e+00, -2.302015482059909e+00, -1.953798704102809e+00, -1.559149296799836e+00, -1.158845632780209e+00, -7.961069108811341e-01, -5.719032993449049e-01, -5.072902785528142e-01, -4.115361651381509e-01, -2.937859021152377e-01, -1.913865400536442e-01, -1.241216845101012e-01, -6.194000754130617e-02, -1.523539909309427e-02, -1.369658131199187e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


